*{box-sizing:border-box} :root{--ink:#f2eff3;--muted:#a9a2ad;--dim:#77717d;--bg:#101016;--panel:#191820;--line:rgba(255,255,255,.1);--rose:#e28b9b;--gold:#e7c48c;--mint:#a7d6bf;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',system-ui,sans-serif}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 75% -15%,#35232f 0,transparent 38%),var(--bg);color:var(--ink);font-family:var(--sans);font-size:14px}button{font:inherit;color:inherit}button:focus-visible{outline:2px solid var(--rose);outline-offset:3px}.shell{max-width:1220px;margin:auto;padding:28px 34px 20px}.topbar{height:46px;display:flex;align-items:center;justify-content:space-between;margin-bottom:24px}.brand{display:flex;align-items:center;gap:12px;letter-spacing:.18em;font-size:11px;font-weight:700}.brand-mark{width:31px;height:31px;border:1px solid #73525d;border-radius:50%;display:grid;place-items:center;color:var(--rose);font-family:var(--serif);font-size:17px;letter-spacing:0}.top-actions{display:flex;align-items:center;gap:10px}.icon-btn,.soft-btn{border:1px solid var(--line);background:#ffffff08;color:#d4ced7;border-radius:8px;cursor:pointer;transition:.2s}.icon-btn{width:38px;height:38px;font-size:16px}.soft-btn{padding:10px 14px;font-size:12px}.icon-btn:hover,.soft-btn:hover{background:#ffffff14;border-color:#ffffff30}.hidden{display:none!important}.title-screen{display:grid;grid-template-columns:1.55fr 1fr;min-height:620px;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#17151c}.title-art{min-height:620px;position:relative;overflow:hidden;background:linear-gradient(180deg,#1d1b2b 0%,#4a2638 57%,#d16d78 100%)}.title-art:before,.scene:before,.ending-art:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(13,12,20,.43),transparent 80%),linear-gradient(0deg,rgba(13,12,20,.72),transparent 55%);z-index:1}.moon{position:absolute;width:135px;height:135px;right:17%;top:12%;border-radius:50%;background:#f4c8bd;box-shadow:0 0 90px #ffb1b475}.cityline{position:absolute;bottom:0;left:0;right:0;height:36%;background:linear-gradient(0deg,#11121a 0 18%,transparent 18%),repeating-linear-gradient(90deg,transparent 0 24px,#181722 24px 62px,transparent 62px 83px);clip-path:polygon(0 26%,5% 26%,5% 6%,13% 6%,13% 30%,19% 30%,19% 0,25% 0,25% 28%,35% 28%,35% 15%,40% 15%,40% 38%,48% 38%,48% 6%,55% 6%,55% 32%,62% 32%,62% 12%,69% 12%,69% 25%,76% 25%,76% 0,81% 0,81% 30%,90% 30%,90% 12%,95% 12%,95% 34%,100% 34%,100% 100%,0 100%)}.title-person,.ending-person{position:absolute;z-index:2;bottom:11%;left:58%;width:145px;height:290px;transform:translateX(-50%);filter:drop-shadow(0 10px 12px #100e17)}.title-person:before,.ending-person:before{content:"";position:absolute;width:73px;height:79px;border-radius:48% 48% 42% 42%;background:#17131c;top:0;left:36px;box-shadow:0 -16px 0 -3px #17131c}.title-person:after,.ending-person:after{content:"";position:absolute;top:70px;left:14px;width:116px;height:220px;background:linear-gradient(90deg,#18141e,#30202a 60%,#17131d);clip-path:polygon(31% 0,69% 0,83% 30%,100% 100%,0 100%,17% 30%);border-radius:40% 40% 0 0}.title-copy{position:absolute;z-index:3;left:9%;bottom:14%;max-width:450px}.eyebrow{font-size:9px;letter-spacing:.2em;color:var(--rose);font-weight:700}.title-copy h1,.ending-copy h1{font:600 clamp(48px,6vw,78px)/.98 var(--serif);letter-spacing:-.04em;margin:19px 0 18px}.title-copy h1 em{color:#f2b5b4;font-weight:500}.title-copy p{color:#e2d7dc;font-size:13px;line-height:1.8;margin:0 0 24px}.primary-btn{border:0;border-radius:7px;background:#e18b9b;color:#20151a;padding:14px 18px;font-size:12px;font-weight:700;cursor:pointer;box-shadow:0 8px 24px #d4677930;transition:.2s}.primary-btn:hover{background:#f0a3ae;transform:translateY(-2px)}.primary-btn span{margin-left:22px;font-size:16px}.title-foot{position:absolute;z-index:3;bottom:24px;left:9%;font-size:8px;letter-spacing:.16em;color:#ffffff88}.title-side{padding:56px 10% 32px;display:flex;flex-direction:column}.side-kicker{font-size:9px;letter-spacing:.19em;color:#bd9caa}.title-side h2{font:500 28px/1.3 var(--serif);margin:18px 0}.title-side>p{color:var(--muted);font-size:12px;line-height:1.85;max-width:290px}.feature-list{margin-top:42px;border-top:1px solid var(--line)}.feature-list>div{display:flex;gap:15px;align-items:center;padding:15px 0;border-bottom:1px solid var(--line);font-size:11px;color:#d8d2dc}.feature-list i{font-style:normal;color:var(--rose);font-size:9px;letter-spacing:.08em}.side-bottom{margin-top:auto;display:flex;gap:8px;color:#756e79;font-size:8px;letter-spacing:.12em;padding-top:35px}.save-note{font-size:10px;color:#f7d8db;margin-top:12px}.game-screen{animation:appear .5s ease}.chapter-row{display:flex;align-items:end;justify-content:space-between;margin:10px 0 18px}.chapter-row h2{font:500 25px var(--serif);margin:6px 0 0}.chapter-count{font:500 19px var(--serif);color:var(--rose)}.chapter-count span{color:var(--dim);font-size:12px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 276px;gap:19px;align-items:start}.main-column{min-width:0}.scene{position:relative;height:345px;overflow:hidden;border:1px solid #ffffff14;border-radius:13px;background:linear-gradient(180deg,#24243a,#604055 66%,#d17d83);isolation:isolate;transition:background .6s}.scene[data-place="platform"]{background:linear-gradient(180deg,#182637,#28536b 65%,#c77d87)}.scene[data-place="alley"]{background:linear-gradient(180deg,#161620,#392333 60%,#a8516a)}.scene[data-place="cafe"]{background:linear-gradient(180deg,#28252b,#59403a 65%,#bd8270)}.scene[data-place="morning"]{background:linear-gradient(180deg,#293b55,#b17486 65%,#e0ad91)}.scene:before{z-index:0}.scene-moon{position:absolute;right:18%;top:12%;width:84px;height:84px;border-radius:50%;background:#f1c7bd;box-shadow:0 0 60px #ffc3c376}.scene .cityline{height:49%;opacity:.9}.scene-grain{position:absolute;inset:0;z-index:1;opacity:.13;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E")}.rain{position:absolute;inset:-40% 0;z-index:2;opacity:.3;background:repeating-linear-gradient(105deg,transparent 0 38px,#ffffff40 39px,#ffffff40 40px,transparent 41px 82px);animation:rain 1.4s linear infinite}.person{position:absolute;z-index:2;bottom:0;width:150px;height:250px;transition:all .6s}.person-left{left:31%}.person-right{left:61%;opacity:.78;transform:scale(.84);transform-origin:bottom}.person .head{position:absolute;top:5px;left:44px;width:60px;height:72px;border-radius:45% 45% 42% 42%;background:linear-gradient(90deg,#211721,#4b3034);box-shadow:0 -14px 0 -2px #211721}.person .body{position:absolute;top:68px;left:16px;width:112px;height:190px;background:linear-gradient(90deg,#17151e,#352530 60%,#1d1720);clip-path:polygon(33% 0,67% 0,82% 28%,100% 100%,0 100%,18% 28%)}.person-right .head{background:linear-gradient(90deg,#1d1d24,#33414a);box-shadow:0 -14px 0 -2px #1d1d24}.person-right .body{background:linear-gradient(90deg,#141923,#293440 60%,#171a22)}.scene[data-cast="solo"] .person-right{opacity:0;transform:translateX(40px) scale(.8)}.scene[data-cast="together"] .person{left:42%}.scene[data-cast="together"] .person-right{left:56%;transform:scale(.78)}.scene-location{position:absolute;z-index:4;top:18px;left:20px;right:20px;display:flex;align-items:center;gap:8px;font-size:8px;font-weight:700;letter-spacing:.15em;color:#fff}.live-dot{height:5px;width:5px;background:var(--rose);border-radius:50%;box-shadow:0 0 9px var(--rose)}.scene-time{margin-left:auto;color:#ffffffa8}.scene-caption{position:absolute;z-index:4;left:22px;bottom:19px;font:italic 14px var(--serif);color:#fff;letter-spacing:.02em}.dialogue{margin-top:13px;background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:20px 22px 18px;min-height:205px}.speaker-row{display:flex;justify-content:space-between;align-items:center}.speaker-name{font-size:9px;letter-spacing:.15em;color:var(--rose);font-weight:700}.scene-progress{font-size:9px;color:var(--dim)}.dialogue-text{font:16px/1.75 var(--serif);color:#ede8ee;margin:13px 0 18px;max-width:760px}.choices{display:grid;gap:8px}.choice{width:100%;text-align:left;display:flex;align-items:center;gap:13px;padding:11px 13px;border:1px solid #ffffff14;border-radius:7px;background:#ffffff04;color:#ded9e0;font-size:11px;cursor:pointer;transition:.2s}.choice:hover{border-color:#d98998a0;background:#e18b9b0c;transform:translateX(3px)}.choice-index{color:#d7909c;font-size:9px}.continue-row{border-top:1px solid var(--line);padding-top:13px;display:flex;justify-content:space-between;align-items:center;color:var(--dim);font-size:10px}.continue-btn{border:0;background:transparent;color:var(--rose);font-size:11px;cursor:pointer;padding:7px}.continue-btn b{font-size:16px;margin-left:12px}.sidebar{display:grid;gap:12px}.side-card{border:1px solid var(--line);border-radius:11px;background:var(--panel);padding:17px}.card-label{font-size:9px;color:#c5a5ae;letter-spacing:.17em;font-weight:700}.compass-intro{font:italic 12px/1.6 var(--serif);color:#a7a0aa;margin:9px 0 18px}.stat{margin:0 0 16px}.stat:last-child{margin-bottom:1px}.stat-head{display:flex;justify-content:space-between;margin-bottom:7px;font-size:10px}.stat-head span:first-child{color:#e3dee5}.stat-word{color:#8f8994}.meter{height:3px;background:#ffffff13;border-radius:8px;overflow:hidden}.meter i{height:100%;display:block;width:45%;background:var(--rose);border-radius:8px;transition:width .5s}.stat[data-stat="clarity"] .meter i{background:#a9c5d2}.stat[data-stat="resolve"] .meter i{background:#c9ae80}.people-card{padding-bottom:8px}.person-note{display:flex;align-items:center;gap:10px;margin:15px 0}.avatar{width:31px;height:31px;border-radius:50%;display:grid;place-items:center;font:14px var(--serif)}.avatar-you{background:#392b3b;color:#e89eaa}.avatar-m{background:#3a2a35;color:#e6a3a2}.avatar-r{background:#2c3940;color:#a8c4ce}.person-note strong,.person-note small{display:block}.person-note strong{font-size:10px;font-weight:600}.person-note small{font-size:9px;color:var(--dim);margin-top:3px}.side-quote{padding:4px 8px 3px 13px;border-left:1px solid #79505b;color:#9e929e;font:italic 12px/1.6 var(--serif)}.restart-link{border:0;background:none;color:#807986;font-size:10px;text-align:left;cursor:pointer;padding:4px 0}.restart-link:hover{color:var(--rose)}footer{display:flex;gap:9px;justify-content:center;color:#5e5963;font-size:8px;letter-spacing:.13em;padding:22px 0 0}footer span{color:#a76b79}.ending-screen{display:grid;grid-template-columns:1fr 1fr;min-height:550px;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#17151c;animation:appear .6s}.ending-art{position:relative;min-height:550px;background:linear-gradient(180deg,#25283a,#6d4054 60%,#d28b8a)}.ending-person{left:53%;bottom:8%;transform:translateX(-50%) scale(1.1)}.ending-copy{padding:70px 10%;align-self:center}.ending-copy h1{font-size:47px;margin:20px 0}.ending-copy>p{font:16px/1.9 var(--serif);color:#d2cbd4}.ending-reflection{border-left:1px solid var(--rose);padding:4px 0 4px 15px;margin:26px 0;color:#a9a2ad;font-size:11px;line-height:1.8}.ending-actions{display:flex;gap:10px;align-items:center;margin-top:28px}.ending-count{color:#77717d;font-size:9px;margin-top:20px}.modal{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:20px}.modal-backdrop{position:absolute;inset:0;background:#08070bd9;backdrop-filter:blur(8px)}.journal{position:relative;width:min(510px,100%);max-height:85vh;overflow:auto;border:1px solid #ffffff1a;border-radius:13px;background:#191820;padding:31px}.modal-close{position:absolute;right:17px;top:14px;background:none;border:0;color:#aaa;font-size:25px;cursor:pointer}.journal h2{font:500 28px var(--serif);margin:9px 0}.journal-sub{font-size:11px;color:var(--muted);margin-bottom:22px}.journal-entry{border-top:1px solid var(--line);padding:14px 0}.journal-entry small{color:var(--rose);font-size:8px;letter-spacing:.13em}.journal-entry p{font:13px/1.65 var(--serif);color:#d9d3dc;margin:7px 0 0}.empty-journal{color:#8e8792;font:italic 13px var(--serif);padding:20px 0}@keyframes rain{to{transform:translate(-25px,80px)}}@keyframes appear{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:850px){.shell{padding:18px 18px 12px}.game-layout{grid-template-columns:minmax(0,1fr) 235px;gap:12px}.title-screen{grid-template-columns:1.2fr 1fr}.title-side{padding:42px 8% 25px}.title-copy{left:7%}.title-foot{left:7%}.scene{height:315px}.person-left{left:26%}.person-right{left:60%}}
@media(max-width:650px){.shell{padding:12px 12px calc(15px + env(safe-area-inset-bottom))}.topbar{margin-bottom:15px}.brand{font-size:9px;letter-spacing:.12em;gap:8px}.brand-mark{width:29px;height:29px}.soft-btn{padding:9px 10px}.title-screen{display:block;min-height:unset}.title-art{min-height:550px}.title-side{padding:25px 24px 22px}.title-side h2{font-size:23px;margin:11px 0}.title-side>p{margin:0;max-width:none}.feature-list{margin-top:20px}.feature-list>div{padding:12px 0}.side-bottom{padding-top:22px;flex-wrap:wrap;font-size:7px}.chapter-row{margin-top:5px}.chapter-row h2{font-size:22px}.game-layout{display:flex;flex-direction:column}.main-column,.sidebar{width:100%}.scene{height:280px}.person{transform:scale(.78);transform-origin:bottom}.person-left{left:20%}.person-right{left:55%}.scene[data-cast="together"] .person{left:32%}.scene[data-cast="together"] .person-right{left:52%;transform:scale(.65)}.dialogue{padding:17px 15px;min-height:195px}.dialogue-text{font-size:15px;line-height:1.7}.choice{padding:12px;font-size:11px}.sidebar{grid-template-columns:1fr 1fr}.side-card{padding:14px}.people-card{grid-column:span 2;display:grid;grid-template-columns:1fr 1fr;align-items:center}.people-card .card-label{grid-column:span 2}.people-card .person-note{margin:11px 0 5px}.side-quote,.restart-link{display:none}.ending-screen{display:flex;flex-direction:column}.ending-art{min-height:280px}.ending-person{transform:translateX(-50%) scale(.78);transform-origin:bottom}.ending-copy{padding:30px 24px 36px}.ending-copy h1{font-size:39px}.ending-copy>p{font-size:14px}.ending-actions{flex-wrap:wrap}.ending-count{margin-top:15px}footer{font-size:7px;text-align:center;line-height:1.6;flex-wrap:wrap}.title-copy h1{font-size:60px}.title-person{transform:translateX(-50%) scale(.85);transform-origin:bottom;left:64%}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

const $=id=>document.getElementById(id);
const fresh=()=>({node:'call',stats:{trust:48,clarity:35,resolve:38},journal:[],visited:0});
const story={
call:{chapter:1,kicker:'CHAPTER ONE',title:'The missed call',place:'platform',time:'11:47 PM',caption:'The city is still awake.',cast:'solo',speaker:'NARRATOR',text:'Mina’s name glows on your phone. You have been together for two years, long enough to recognize the careful pause before she says “I’m fine.” Tonight, you hear it before she even picks up.',choices:[['Call her back. Ask what’s really going on.',{trust:5,clarity:5},'train'],['Send a light message. Give her room to answer.',{trust:4,resolve:3},'train'],['Take the next train to the address she sent.',{resolve:7,clarity:2},'station']]},
train:{chapter:1,kicker:'CHAPTER ONE',title:'The missed call',place:'platform',time:'11:54 PM',caption:'A train sighs into the station.',cast:'solo',speaker:'MINA · TEXT',text:'“I’m at the west exit. Could you come? There’s something I should tell you in person.” The message is followed by three dots, then nothing. On the dark window, your reflection looks like someone waiting for a verdict.',choices:[['Reply: “I’m coming. We’ll talk, no pressure.”',{trust:5,resolve:3},'station'],['Ask who else is there before you go.',{clarity:7,trust:-2},'station'],['Put your phone away and get on the train.',{resolve:4,trust:-2},'station']]},
station:{chapter:1,kicker:'CHAPTER ONE',title:'West exit',place:'platform',time:'12:08 AM',caption:'Rain turns the pavement to glass.',cast:'together',speaker:'MINA',text:'Mina stands beneath the station clock. Her hair is damp, her hands wrapped around a paper cup gone cold. Before she can speak, another figure steps out from the rain: Ren, her old university friend. The three of you have met once. “I didn’t know you were coming,” Ren says.',choices:[['Greet Ren, then turn to Mina and let her speak.',{trust:6,resolve:3},'reveal'],['Ask Mina directly why Ren is here.',{clarity:6,trust:-4},'reveal'],['Keep your distance. Watch how they act together.',{clarity:4,trust:-3},'reveal']]},
reveal:{chapter:2,kicker:'CHAPTER TWO',title:'What you saw',place:'alley',time:'12:11 AM',caption:'The clock keeps moving, even now.',cast:'together',speaker:'MINA',text:'“Ren called because their mother’s in hospital,” Mina says. “I came to help them find a place to stay. I should have told you.” Ren looks down. “We used to date. Years ago. Mina didn’t want this to become a whole thing.” The omission hangs heavier than the rain.',choices:[['Ask Mina what made it hard to tell you.',{trust:4,clarity:6},'response'],['Ask Ren to give you both a little privacy.',{resolve:5,clarity:2},'private'],['Say nothing yet. You need a minute.',{resolve:4,trust:1},'quiet']]},
response:{chapter:2,kicker:'CHAPTER TWO',title:'The part left out',place:'alley',time:'12:14 AM',caption:'A taxi passes, bright as a match.',cast:'together',speaker:'MINA',text:'“I thought you’d hear ‘ex’ and stop listening,” Mina says. “That wasn’t fair to you.” She looks exhausted, not rehearsed. Ren shifts under the awning. You can feel the shape of the question you came here carrying, but not yet its answer.',choices:[['Tell her the omission hurt more than the past.',{trust:7,clarity:6},'private'],['Ask what boundaries they have with each other now.',{clarity:8,resolve:2},'private'],['Tell her you don’t want to decide anything tonight.',{resolve:7,trust:2},'private']]},
private:{chapter:3,kicker:'CHAPTER THREE',title:'A table for three',place:'cafe',time:'12:32 AM',caption:'The little café is almost closing.',cast:'together',speaker:'REN',text:'“For what it’s worth, I’m sorry you found out like this,” Ren says, leaving the choice of whether to stay to you. Mina doesn’t reach for your hand. She doesn’t ask you to reassure her. The quiet is uncomfortable—and, for once, nobody is trying to fill it for you.',choices:[['Invite Ren to explain, then decide what you need from Mina.',{clarity:8,trust:3},'listen'],['Ask Mina for the conversation you came to have—just you two.',{resolve:6,trust:4},'listen'],['Say you’re going home alone. You can talk tomorrow.',{resolve:10,trust:-2},'listen']]},
quiet:{chapter:3,kicker:'CHAPTER THREE',title:'A table for three',place:'cafe',time:'12:32 AM',caption:'The little café is almost closing.',cast:'together',speaker:'MINA',text:'“We can take this at your pace,” Mina says. Ren offers a small nod, then turns their cup between both hands. Outside, the rain thins to mist. It occurs to you that being hurt and being sure are not the same thing.',choices:[['Ask them both to stay while you set some ground rules.',{clarity:7,resolve:4},'listen'],['Ask Mina to walk with you. You need to hear her alone.',{trust:4,resolve:5},'listen'],['Take a little space and revisit this in the morning.',{resolve:9,trust:1},'listen']]},
listen:{chapter:3,kicker:'CHAPTER THREE',title:'The question beneath it',place:'cafe',time:'12:49 AM',caption:'The last train is already gone.',cast:'together',speaker:'NARRATOR',text:'Ren explains the call: an urgent ride to the hospital, a spare room to find, and an old friendship that has never been quite simple. Mina fills in what Ren leaves out. Nothing in their story proves betrayal. Nothing erases the choice to keep it from you. Both things can be true.',choices:[['Tell Mina trust will take honesty, not promises.',{trust:7,clarity:7,resolve:3},'dawn'],['Tell Mina you need distance before you can talk freely.',{resolve:8,clarity:4,trust:-1},'dawn'],['Ask what the two of you want this relationship to be.',{clarity:6,trust:4,resolve:4},'dawn']]},
dawn:{chapter:4,kicker:'CHAPTER FOUR',title:'First light',place:'morning',time:'5:16 AM',caption:'The sky begins again in pale gold.',cast:'solo',speaker:'MINA',text:'At the river, Mina walks beside you without touching. “I’m sorry I made a choice for you by leaving things out,” she says. The first train rumbles overhead. There are no perfect words waiting on the other side of this night—only the next choice, and the one after that.',choices:[['Try again, with clearer boundaries and honest check-ins.',{trust:8,clarity:4,resolve:2},'end'],['Take time apart. Let actions speak before deciding.',{resolve:8,clarity:5,trust:1},'end'],['End the relationship kindly. This isn’t what you need.',{resolve:10,clarity:6,trust:-2},'end']]},
end:{chapter:4,kicker:'CHAPTER FOUR',title:'Morning, at last',place:'morning',time:'5:31 AM',caption:'A new day doesn’t need a tidy answer.',cast:'solo',speaker:'NARRATOR',text:'The sky has changed color. So have you, a little. You don’t owe anyone a quick answer—not Mina, not Ren, not the worried version of yourself that filled in every silence. The city opens around you, ordinary and enormous.',choices:[['See where the morning takes you.',{},'finish']]}
};
let state=fresh();let soundOn=true;
function save(){try{localStorage.setItem('afterLastTrainSave',JSON.stringify(state))}catch(e){}}
function load(){try{const d=JSON.parse(localStorage.getItem('afterLastTrainSave'));return d&&story[d.node]?d:null}catch(e){return null}}
function begin(resume=false){state=resume?(load()||fresh()):fresh();$('titleScreen').classList.add('hidden');$('endingScreen').classList.add('hidden');$('gameScreen').classList.remove('hidden');render();window.scrollTo({top:0,behavior:'smooth'})}
function render(){const n=story[state.node];if(!n)return;document.querySelector('.chapter-row').classList.remove('hidden');$('chapterKicker').textContent=n.kicker;$('chapterTitle').textContent=n.title;$('chapterCount').innerHTML=`0${n.chapter} <span>/ 04</span>`;$('locationLabel').textContent=({platform:'SHINJUKU STATION',alley:'WEST EXIT · BACK STREET',cafe:'KISSA AO · WEST EXIT',morning:'SUMIDA RIVER'})[n.place];$('timeLabel').textContent=n.time;$('sceneCaption').textContent=n.caption;const scene=$('scene');scene.dataset.place=n.place;scene.dataset.cast=n.cast;$('speaker').textContent=n.speaker;$('dialogueText').textContent=n.text;$('sceneProgress').textContent=`${String(Math.min(state.visited+1,9)).padStart(2,'0')} / 09`;
const choices=$('choices');choices.innerHTML='';$('continueRow').classList.add('hidden');if(n.choices){n.choices.forEach((c,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="choice-index">0${i+1}</span><span>${c[0]}</span>`;b.onclick=()=>choose(c);choices.appendChild(b)})}else{$('continueRow').classList.remove('hidden')};updateStats();save()}
